#include <stdio.h>

int main() {
    unsigned int flags = 0;          // 00000000

    flags |= (1 << 2);                // set bit 2  -> 00000100
    flags |= (1 << 4);                // set bit 4  -> 00010100
    printf("%u\n", flags);             // 20

    flags &= ~(1 << 2);                // clear bit 2 -> 00010000
    printf("%u\n", flags);             // 16

    printf("%d\n", (flags & (1 << 4)) != 0);   // 1 — bit 4 is still set

    flags ^= (1 << 4);                 // toggle bit 4 -> 00000000
    printf("%u\n", flags);             // 0
    return 0;
}
